?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($title)?> — SmartToolz</title><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#172033;font-family:Inter,system-ui,Arial,sans-serif}.wrap{width:min(980px,calc(100% - 28px));margin:38px auto 70px}.hero,.tool{background:#fff;border:1px solid #e5e9f0;border-radius:22px;box-shadow:0 15px 45px #1d27400d}.hero{padding:30px;margin-bottom:18px}.tag{color:#635bff;font-size:11px;font-weight:900;letter-spacing:1px}.hero h1{font-size:clamp(30px,5vw,48px);letter-spacing:-2px;margin:7px 0}.hero p{color:#707b8e}.tool{padding:25px}.input,textarea,select{width:100%;padding:12px;border:1px solid #dfe4ec;border-radius:11px;margin:6px 0 12px;font:inherit}textarea{min-height:190px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{border:0;border-radius:11px;padding:12px 17px;background:#635bff;color:#fff;font-weight:800;cursor:pointer}.btn.alt{background:#edf0f5;color:#273147}.out{margin-top:14px;padding:15px;border:1px solid #e5e9f0;border-radius:12px;background:#f7f8fb;white-space:pre-wrap;word-break:break-word}.drop{padding:35px;text-align:center;border:2px dashed #d7dbee;border-radius:16px;color:#707b8e;cursor:pointer}.center{text-align:center}@media(max-width:650px){.row{grid-template-columns:1fr}.hero,.tool{padding:21px}}</style></head><body><main class="wrap"><section class="hero"><div class="tag">SMARTTOOLZ TOOL</div><h1><?=htmlspecialchars($title)?></h1><p>Simple, fast and responsive. Processing happens in your browser whenever possible.</p></section><section class="tool" id="app"></section></main><?php require_once __DIR__.'/footer.php';?><script>
(function(){'use strict';const S=<?=json_encode($slug)?>,A=document.getElementById('app'),$=s=>A.querySelector(s),dl=(b,n)=>{const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=n;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
function text(k){A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES)?></h2><textarea id="i" placeholder="Enter text..."></textarea><button class="btn" id="go">Process</button><button class="btn alt" id="cp">Copy</button><div class="out" id="o"></div>';$('#go').onclick=()=>{let s=$('#i').value,o=s;if(k==='word')o='Words: '+(s.trim()?s.trim().split(/\s+/).length:0)+'\nCharacters: '+s.length+'\nNo spaces: '+s.replace(/\s/g,'').length+'\nLines: '+(s?s.split(/\r?\n/).length:0);if(k==='case')o=s.toUpperCase();if(k==='dup')o=[...new Set(s.split(/\r?\n/))].join('\n');if(k==='spaces')o=s.replace(/[ \t]+/g,' ').replace(/^ +| +$/gm,'');if(k==='sort')o=s.split(/\r?\n/).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'})).join('\n');if(k==='reverse')o=[...s].reverse().join('');if(k==='slug')o=s.toLowerCase().trim().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-');if(k==='markdown')o=s.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>');$('#o').textContent=o};$('#cp').onclick=()=>navigator.clipboard?.writeText($('#o').textContent)}
function codec(k){A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES)?></h2><textarea id="i"></textarea><button class="btn" id="go">Process</button><textarea id="o" readonly></textarea>';$('#go').onclick=()=>{try{const s=$('#i').value;let o;if(k==='b64e')o=btoa(unescape(encodeURIComponent(s)));else if(k==='b64d')o=decodeURIComponent(escape(atob(s)));else if(k==='ue')o=encodeURIComponent(s);else if(k==='ud')o=decodeURIComponent(s);else if(k==='he')o=s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));else{const t=document.createElement('textarea');t.innerHTML=s;o=t.value}$('#o').value=o}catch(e){$('#o').value='Invalid input: '+e.message}}}
function calc(k){let h='';if(k==='age')h='<h2>Age Calculator</h2><input id="d" class="input" type="date">';if(k==='pct')h='<h2>Percentage Calculator</h2><div class="row"><input id="a" class="input" type="number" placeholder="Percentage"><input id="b" class="input" type="number" placeholder="Number"></div>';if(k==='bmi')h='<h2>BMI Calculator</h2><div class="row"><input id="w" class="input" type="number" placeholder="Weight kg"><input id="h" class="input" type="number" placeholder="Height cm"></div>';if(k==='unit')h='<h2>Unit Converter</h2><input id="v" class="input" type="number" value="1"><div class="row"><select id="f"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select><select id="t"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select></div>';A.innerHTML=h+'<button class="btn" id="go">Calculate</button><div class="out" id="o"></div>';$('#go').onclick=()=>{let o='';if(k==='age'){if(!$('#d').value)return;o=(new Date().getFullYear()-new Date($('#d').value).getFullYear())+' years (approx.)'}else if(k==='pct')o=((+$('#a').value*+$('#b').value)/100).toFixed(2);else if(k==='bmi'){const x=+$('#h').value/100;o=(+$('#w').value/(x*x)).toFixed(2)}else{const z={m:1,km:1000,ft:.3048,mi:1609.344,kg:1,lb:.453592};o=((+$('#v').value*z[$('#f').value])/z[$('#t').value]).toFixed(6)+' '+$('#t').value}$('#o').textContent=o}}
function gen(k){if(k==='uuid'){A.innerHTML='<h2>UUID Generator</h2><button class="btn" id="go">Generate</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=crypto.randomUUID();return}if(k==='random'){A.innerHTML='<h2>Random Number Generator</h2><div class="row"><input id="a" class="input" type="number" value="1"><input id="b" class="input" type="number" value="100"></div><button class="btn" id="go">Generate</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=Math.floor(Math.random()*(+$('#b').value-+$('#a').value+1))+ +$('#a').value;return}if(k==='lorem'){A.innerHTML='<h2>Lorem Ipsum Generator</h2><input id="n" class="input" type="number" value="3" min="1" max="20"><button class="btn" id="go">Generate</button><textarea id="o"></textarea>';$('#go').onclick=()=>$('#o').value=Array.from({length:+$('#n').value},()=> 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.').join('\n\n');return}A.innerHTML='<h2>QR Code Generator</h2><input id="i" class="input" placeholder="Text or URL"><button class="btn" id="go">Create QR</button><div class="center"><canvas id="qr"></canvas></div>';$('#go').onclick=()=>QRCode.toCanvas($('#qr'),$('#i').value||'SmartToolz',{width:280})}
function pdfImg(ext){A.innerHTML='<h2>PDF to '+ext.toUpperCase()+'</h2><input id="f" class="input" type="file" accept="application/pdf"><button class="btn" id="go">Convert</button><div class="out" id="o"></div>';$('#go').onclick=async()=>{const f=$('#f').files[0];if(!f)return;const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise;for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),v=p.getViewport({scale:1.5}),c=document.createElement('canvas');c.width=v.width;c.height=v.height;await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;const b=await new Promise(r=>c.toBlob(r,'image/'+ext));dl(b,`page-${i}.${ext==='jpeg'?'jpg':'png'}`)}$('#o').textContent='Done.'}}
function pdf(k){A.innerHTML='<h2>PDF '+k+'</h2><input id="f" class="input" type="file" accept="application/pdf" '+(k==='merge'?'multiple':'')+'><button class="btn" id="go">Process & Download</button><div class="out" id="o"></div>';$('#go').onclick=async()=>{const fs=$('#f').files;if(!fs.length)return;if(k==='merge'){const out=await PDFLib.PDFDocument.create();for(const f of fs){const p=await PDFLib.PDFDocument.load(await f.arrayBuffer());(await out.copyPages(p,p.getPageIndices())).forEach(x=>out.addPage(x))}dl(new Blob([await out.save()],{type:'application/pdf'}),'merged.pdf')}else if(k==='split'){const src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer()),zip=new JSZip();for(let i=0;i<src.getPageCount();i++){const d=await PDFLib.PDFDocument.create(),[p]=await d.copyPages(src,[i]);d.addPage(p);zip.file('page-'+(i+1)+'.pdf',await d.save())}dl(await zip.generateAsync({type:'blob'}),'split-pdf.zip')}else{const src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());dl(new Blob([await src.save()],{type:'application/pdf'}),'compressed.pdf')}$('#o').textContent='Done.'}}
function imgPdf(){A.innerHTML='<h2>PNG to PDF</h2><input id="f" class="input" type="file" accept="image/png,image/jpeg" multiple><button class="btn" id="go">Create PDF</button>';$('#go').onclick=async()=>{const {jsPDF}=jspdf,doc=new jsPDF();let first=true;for(const f of $('#f').files){const im=new Image(),u=URL.createObjectURL(f);await new Promise(r=>{im.onload=r;im.src=u});if(!first)doc.addPage();first=false;const z=Math.min(190/im.width,270/im.height);doc.addImage(im,f.type==='image/png'?'PNG':'JPEG',10,10,im.width*z,im.height*z);URL.revokeObjectURL(u)}dl(doc.output('blob'),'images.pdf')}}
function txtPdf(){A.innerHTML='<h2>Text to PDF</h2><textarea id="i" placeholder="Enter text..."></textarea><button class="btn" id="go">Download PDF</button>';$('#go').onclick=()=>{const {jsPDF}=jspdf,doc=new jsPDF();doc.text(doc.splitTextToSize($('#i').value,180),15,20);dl(doc.output('blob'),'text.pdf')}}
function qrRead(){A.innerHTML='<h2>QR Code Reader</h2><input id="f" class="input" type="file" accept="image/*"><div class="out" id="o">Choose an image.</div>';$('#f').onchange=()=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height),r=jsQR(d.data,d.width,d.height);$('#o').textContent=r?r.data:'No QR code detected.'};im.src=URL.createObjectURL($('#f').files[0])}}
function color(){A.innerHTML='<h2>Color Converter</h2><input id="h" class="input" value="#635bff"><button class="btn" id="go">Convert</button><div class="out" id="o"></div>';$('#go').onclick=()=>{const m=$('#h').value.match(/^#([0-9a-f]{6})$/i);if(!m)return $('#o').textContent='Invalid HEX color';const x=m[1];$('#o').textContent='HEX: #'+x.toUpperCase()+'\nRGB: '+parseInt(x.slice(0,2),16)+', '+parseInt(x.slice(2,4),16)+', '+parseInt(x.slice(4),16)}}
function stamp(){A.innerHTML='<h2>Timestamp Converter</h2><input id="v" class="input" type="number" placeholder="Unix timestamp"><button class="btn" id="go">Convert</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=new Date(+$('#v').value*1000).toString()}
function unix(){A.innerHTML='<h2>Unix Timestamp</h2><button class="btn" id="go">Get Timestamp</button><div class="out" id="o"></div>';$('#go').onclick=()=>$('#o').textContent=Math.floor(Date.now()/1000)}
function watch(){A.innerHTML='<h2>Stopwatch / Timer</h2><div class="out" id="o">00:00:00.000</div><button class="btn" id="s">Start</button> <button class="btn alt" id="p">Stop</button> <button class="btn alt" id="r">Reset</button>';let t=0,st=0,it=null;const draw=()=>{const z=t+(it?Date.now()-st:0),d=new Date(z);$('#o').textContent=d.toISOString().slice(11,23)};$('#s').onclick=()=>{if(!it){st=Date.now();it=setInterval(draw,30)}};$('#p').onclick=()=>{if(it){t+=Date.now()-st;clearInterval(it);it=null;draw()}};$('#r').onclick=()=>{clearInterval(it);it=null;t=0;draw()}}
const m={'word-counter':()=>text('word'),'case-converter':()=>text('case'),'remove-duplicate-lines':()=>text('dup'),'remove-extra-spaces':()=>text('spaces'),'sort-lines':()=>text('sort'),'reverse-text':()=>text('reverse'),'text-to-slug':()=>text('slug'),'markdown-to-html':()=>text('markdown'),'base64-encoder':()=>codec('b64e'),'base64-decoder':()=>codec('b64d'),'url-encoder':()=>codec('ue'),'url-decoder':()=>codec('ud'),'html-encoder':()=>codec('he'),'html-decoder':()=>codec('hd'),'json-formatter':()=>A.innerHTML='<h2>JSON Formatter</h2><textarea id="i"></textarea><button class="btn" id="go">Format</button><div class="out" id="o"></div>', 'age-calculator':()=>calc('age'),'percentage-calculator':()=>calc('pct'),'bmi-calculator':()=>calc('bmi'),'unit-converter':()=>calc('unit'),'random-number-generator':()=>gen('random'),'uuid-generator':()=>gen('uuid'),'lorem-ipsum-generator':()=>gen('lorem'),'qr-generator':()=>gen('qr'),'qr-reader':qrRead,'color-converter':color,'timestamp-converter':stamp,'unix-timestamp':unix,'stopwatch-timer':watch,'pdf-merger':()=>pdf('merge'),'pdf-splitter':()=>pdf('split'),'pdf-compressor':()=>pdf('compress'),'pdf-to-jpg':()=>pdfImg('jpeg'),'pdf-to-png':()=>pdfImg('png'),'png-to-pdf':imgPdf,'text-to-pdf':txtPdf};
if(S==='json-formatter'){m[S]();$('#go').onclick=()=>{try{$('#o').textContent=JSON.stringify(JSON.parse($('#i').value),null,2)}catch(e){$('#o').textContent='Invalid JSON: '+e.message}}}else if(m[S])m[S]();else A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES)?></h2><p>This tool is available in SmartToolz. Please use the dedicated tool page from All Tools.</p>';
})();</script></body></html>
